class FitnessTracker:
    NORMAL_BMI_MALE_LOW = 20
    NORMAL_BMI_MALE_HIGH = 25
    NORMAL_BMI_FEMALE_LOW = 19
    NORMAL_BMI_FEMALE_HIGH = 24

    CALORIE_MULTIPLIER_SEDENTARY = 1.2
    CALORIE_MULTIPLIER_ACTIVE = 1.6
    CALORIE_MULTIPLIER_MODERATE = 1.4

    BMR_MALE_CONSTANT = 5
    BMR_FEMALE_CONSTANT = -161

    BMR_WEIGHT_FACTOR = 10
    BMR_HEIGHT_FACTOR = 6.25
    BMR_AGE_FACTOR = 5

    def __init__(self, height, weight, age, sex) -> None:
        self._height = height
        self._weight = weight
        self._age = age
        self._sex = sex

    @property
    def height(self):
        return self._height

    @height.setter
    def height(self, value):
        self._height = value

    @property
    def weight(self):
        return self._weight

    @weight.setter
    def weight(self, value):
        self._weight = value

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        self._age = value

    @property
    def sex(self):
        return self._sex

    @sex.setter
    def sex(self, value):
        self._sex = value

    def get_BMI(self):
        return self._weight / self._height ** 2

    def _get_standard_bmi_range(self):
        if self._sex == "male":
            return [self.NORMAL_BMI_MALE_LOW, self.NORMAL_BMI_MALE_HIGH]
        else:
            return [self.NORMAL_BMI_FEMALE_LOW, self.NORMAL_BMI_FEMALE_HIGH]

    def _calculate_bmr(self):
        base_bmr = (
            self.BMR_WEIGHT_FACTOR * self._weight +
            self.BMR_HEIGHT_FACTOR * self._height -
            self.BMR_AGE_FACTOR * self._age
        )
        if self._sex == "male":
            return base_bmr + self.BMR_MALE_CONSTANT
        else:
            return base_bmr + self.BMR_FEMALE_CONSTANT

    def condition_judge(self):
        bmi = self.get_BMI()
        bmi_range = self._get_standard_bmi_range()
        if bmi > bmi_range[1]:
            # too fat
            return 1
        elif bmi < bmi_range[0]:
            # too thin
            return -1
        else:
            # normal
            return 0

    def calculate_calorie_intake(self):
        bmr = self._calculate_bmr()
        condition = self.condition_judge()
        if condition == 1:
            multiplier = self.CALORIE_MULTIPLIER_SEDENTARY
        elif condition == -1:
            multiplier = self.CALORIE_MULTIPLIER_ACTIVE
        else:
            multiplier = self.CALORIE_MULTIPLIER_MODERATE
        return bmr * multiplier
